#include <stdio.h>



int main(void) {
    int n, composite[10001] = {0};
    scanf("%d", &n);
    for (int p = 2; p <= n / p; p++)
        if (!composite[p]) for (int k = p*p; k <= n; k += p) composite[k] = 1;
    for (int p = 2; p <= n; p++) if (!composite[p]) printf("%d ", p);
    putchar('\n');
    return 0;
}
